import React, { useState } from 'react';
import './Dashboard.css';
import Navbar from '../Components/Navbar';
import Sidebar from '../Components/Sidebar';
import UploadFile from '../Components/UploadFile';

const Dashboard = () => {
  const [selectedFile, setSelectedFile] = useState(null);

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="main-content">
        <Sidebar />
        <div className="dashboard-content">
          <div className="header">
            <h1 className="main-title">
              Unveiling the Power of Test Case Generation
              <br />
              and Execution
            </h1>
            <p className="subtitle">
              Software testing with automated case generation, execution, and meticulous scrutiny, ensuring precision
              and efficiency in development workflows.
            </p>
          </div>

          <div className="upload-section">
            <UploadFile />
          </div>

          <div className="generate-section">
            <div className="generate-input">
              <input
                type="text"
                placeholder="Generate 10 email and password in CSV format"
                className="generate-textfield"
              />
              <button className="start-button">Start</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
